<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {api,get,post} from '../api'
import {directions} from '../industry'
const route=useRoute(),router=useRouter()
const companies=ref<any[]>([]),events=ref<any[]>([]),profile=ref<any>(null),loading=ref(false),error=ref(false),task=ref<any>(null)
const companyId=ref<number|undefined>(),tag=ref(''),stage=ref(''),dialog=ref(false),sourceDialog=ref(false),projectDialog=ref(false),evidence=ref<any>(null),snapshot=ref<any>(null),snapshots=ref<any[]>([]),drawer=ref(false),report=ref<any>(null)
const form=ref({name:'',category:'待研究',official_url:'',description:'',technology_tags:[] as string[]})
const editSourceId=ref<number|null>(null)
const source=ref({company_id:0,project_id:null as number|null,url:'',source_type:'official_website',evidence_authority:'company_claim'})
const project=ref({company_id:0,name:'',description:'',technology_tags:[] as string[]})
const types=['official_website','company_news','wechat_official_account','github','arxiv','technical_blog','industry_media','press_release','customer_case','video','job_posting','other']
const stages=['research','prototype','demonstration','pilot','commercial_deployment','scaled_production','unknown']
const labels:Record<string,string>={research:'技术研究',prototype:'原型',demonstration:'真机/功能演示',pilot:'客户试点',commercial_deployment:'商业部署',scaled_production:'规模化生产',unknown:'未知',company_claim:'企业自述',technical_artifact:'技术产物',independent_verification:'独立验证',customer_confirmation:'客户确认',technology_breakthrough:'技术突破声明',model_release:'模型发布',product_release:'产品发布',robot_demo:'机器人演示',benchmark_result:'基准结果',open_source_release:'开源发布',pilot_deployment:'试点',customer_cooperation:'客户合作',funding:'融资',mass_production:'量产声明',other:'其他'}
const label=(s:string)=>labels[s]||s
const section=computed(()=>route.params.id?'profile':route.path.slice(1))
const title=computed(()=>({companies:'企业情报',feed:'行业动态',tracker:'发展进展追踪',industry:'行业技术地图',profile:profile.value?.name||'企业档案'} as any)[section.value])
const tags=computed(()=>[...new Set(events.value.flatMap(directions))] as string[])
const mapCompanies=computed(()=>companies.value.filter(c=>events.value.some(e=>e.company_id===c.id)).sort((a,b)=>events.value.filter(e=>e.company_id===b.id).length-events.value.filter(e=>e.company_id===a.id).length))
const mapEvents=ref<any[]>([])
const mapCell=(id:number,t:string)=>events.value.filter(e=>e.company_id===id&&directions(e).includes(t))
const names=(id:number)=>companies.value.find(c=>c.id===id)?.name||String(id)
async function load(){loading.value=true;error.value=false;try{companies.value=await get('/companies?limit=200');profile.value=route.params.id?await get('/companies/'+route.params.id):null;const params=new URLSearchParams({limit:'200'});const id=route.params.id||companyId.value;if(id)params.set('company_id',String(id));if(tag.value)params.set('tag',tag.value);if(stage.value)params.set('stage',stage.value);if(section.value==='industry'){const all:any[]=[];for(let offset=0;;offset+=200){params.set('offset',String(offset));const chunk=await get('/progress-events?'+params);all.push(...chunk);if(chunk.length<200)break}events.value=all}else events.value=await get('/progress-events?'+params)}catch{error.value=true}finally{loading.value=false}}
async function save(){await post('/companies',form.value);dialog.value=false;await load()}
async function edit(c:any){await api.patch('/companies/'+c.id,{category:c.category,description:c.description,official_url:c.official_url,technology_tags:c.technology_tags,is_active:c.is_active});ElMessage.success('已保存');await load()}
async function addSource(){if(editSourceId.value)await api.patch('/company-sources/'+editSourceId.value,{url:source.value.url,source_type:source.value.source_type});else await post('/company-sources',source.value);sourceDialog.value=false;await load()}
function openSource(id?:number){editSourceId.value=null;source.value={company_id:id||companies.value[0]?.id||0,project_id:null,url:'',source_type:'official_website',evidence_authority:'company_claim'};sourceDialog.value=true}
function editSource(s:any){editSourceId.value=s.id;source.value={company_id:s.company_id,project_id:s.project_id,url:s.url,source_type:s.source_type,evidence_authority:s.evidence_authority};sourceDialog.value=true}
async function saveProject(){await post('/projects',project.value);projectDialog.value=false;await load()}
async function runSource(s:any){task.value=await post('/sources/'+s.id+'/fetch');ElMessage.success('采集和事件研究已提交；已有产品来源仍沿用原流程')}
async function showSnapshots(s:any){snapshots.value=await get('/sources/'+s.id+'/snapshots');evidence.value=null;snapshot.value=null;drawer.value=true}
async function runSnapshot(id:number){task.value=await post('/snapshots/'+id+'/progress');ElMessage.success('企业进展提取已提交')}
async function showEvidence(e:any){snapshots.value=[];evidence.value=await get('/event-evidence/'+e.evidence_ids[0]);snapshot.value=await get('/snapshots/'+evidence.value.snapshot_id);drawer.value=true}
async function weekly(){report.value=await post('/industry-reports');ElMessage.success('周报已保存到研究报告')}
function download(){const url=URL.createObjectURL(new Blob([report.value.markdown],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='industry-weekly.md';a.click();URL.revokeObjectURL(url)}
let timer:ReturnType<typeof setInterval>
onMounted(()=>{load();timer=setInterval(async()=>{if(task.value&&['queued','running'].includes(task.value.status)){task.value=await get('/tasks/'+task.value.id);if(!['queued','running'].includes(task.value.status))await load()}},4000)})
onUnmounted(()=>clearInterval(timer));watch(()=>route.fullPath,()=>{tag.value='';stage.value='';load()})
</script>
<template><div v-loading="loading"><div class="page-heading"><div><div class="eyebrow">COMPANY INTELLIGENCE / EMBODIED AI</div><h1>{{title}}</h1><p>跟踪公开进展，区分企业自述、技术产物与独立证据。</p></div><div class="actions"><el-button @click="load">刷新</el-button><el-button @click="weekly">生成最近一周行业报告</el-button><el-button type="primary" @click="dialog=true">新增企业</el-button></div></div><el-alert v-if="error" title="加载失败，请检查服务后刷新" type="error"/><div class="notice">发展阶段属于具体事件，不代表企业所有产品都已达到该阶段。日期未知的事件不会被当作本周新闻。</div><section v-if="task" class="panel"><h3>任务 #{{task.id}} · {{task.status}}</h3><el-progress :percentage="task.progress"/><p v-for="(log,i) in task.logs" :key="i">{{log.message}}</p><router-link to="/tasks">查看任务记录 →</router-link></section>
<template v-if="section==='companies'"><div class="product-grid"><section v-for="c in companies" :key="c.id" class="panel"><span class="pill">{{c.is_active?'监测档案':'已停用'}} · {{c.category}}</span><h2 style="margin-top:20px"><router-link :to="'/companies/'+c.id">{{c.name}} ↗</router-link></h2><p>{{c.description||'研究资料待补充，不预设企业成果。'}}</p><p>{{c.technology_tags.join(' · ')||'技术方向待证据验证'}}</p><el-button @click="openSource(c.id)">添加数据源</el-button><el-button @click="c.is_active=!c.is_active;edit(c)">{{c.is_active?'停用':'启用'}}</el-button></section></div></template>
<template v-else-if="section==='profile'&&profile"><section class="panel"><h2>企业资料</h2><el-form label-position="top"><el-form-item label="分类"><el-input v-model="profile.category"/></el-form-item><el-form-item label="简介"><el-input v-model="profile.description" type="textarea"/></el-form-item><el-form-item label="官网"><el-input v-model="profile.official_url"/></el-form-item><el-form-item label="技术方向（人工维护，不自动当作已证实能力）"><el-select v-model="profile.technology_tags" multiple filterable allow-create default-first-option/></el-form-item><el-button @click="edit(profile)">保存资料</el-button></el-form></section><section class="panel"><div class="section-heading"><h2>产品与项目</h2><el-button @click="project={company_id:profile.id,name:'',description:'',technology_tags:[]};projectDialog=true">添加项目</el-button></div><p v-for="p in profile.products" :key="'p'+p.id">产品：<router-link :to="'/products/'+p.id">{{p.name}}</router-link></p><p v-for="p in profile.projects" :key="p.id">项目：{{p.name}} · {{p.technology_tags.join(' / ')}}</p><p v-if="!profile.projects.length&&!profile.products.length">尚未建立产品或项目档案。</p></section><section class="panel"><div class="section-heading"><h2>公开数据源</h2><el-button @click="openSource(profile.id)">添加来源 / 导入公众号文章</el-button></div><div v-for="s in profile.sources" :key="s.id" class="source-row"><div class="grow"><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.url}}</a><p>{{s.source_type}} · {{s.last_status}} · {{s.last_fetched_at||'尚未采集'}}</p><p v-if="s.error" class="error-text">{{s.error}}</p></div><el-button @click="editSource(s)">编辑</el-button><el-button @click="showSnapshots(s)">快照/提取</el-button><el-button :disabled="!s.is_active" @click="runSource(s)">采集研究</el-button><el-button @click="api.patch('/sources/'+s.id,{is_active:!s.is_active}).then(load)">{{s.is_active?'停用':'启用'}}</el-button></div></section><h2>企业发展时间线</h2></template>
<template v-if="section!=='companies'"><div class="toolbar"><el-select v-if="section!=='profile'" v-model="companyId" clearable placeholder="全部企业" style="width:200px" @change="load"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select><el-input v-model="tag" placeholder="按技术方向筛选，如 VLA" style="width:240px" @keyup.enter="load"/><el-select v-model="stage" clearable placeholder="全部阶段" style="width:180px" @change="load"><el-option v-for="s in stages" :key="s" :label="label(s)" :value="s"/></el-select><el-button @click="load">筛选</el-button></div>
<template v-if="section==='tracker'"><section class="panel" v-for="s in stages" :key="s"><h2>{{label(s)}} · {{events.filter(e=>e.progress_stage===s).length}}</h2><button class="matrix-claim" v-for="e in events.filter(e=>e.progress_stage===s)" :key="e.id" @click="showEvidence(e)">{{names(e.company_id)}} · {{e.title}} · {{label(e.evidence_level)}} ↗</button><p v-if="!events.some(e=>e.progress_stage===s)">暂无已保存事件</p></section></template>
<template v-else-if="section==='industry'"><section class="panel"><h2>按证据记录观察技术方向</h2><p>已加载 {{events.length}} 条事件，涉及 {{mapCompanies.length}} 家企业。默认只展示有记录的企业；方向按原始技术标签归类，空白不代表企业没有该能力。</p><div class="matrix-wrap"><table class="matrix"><thead><tr><th>技术方向</th><th v-for="c in mapCompanies" :key="c.id">{{c.name}}</th></tr></thead><tbody><tr v-for="t in tags" :key="t"><th>{{t}}</th><td v-for="c in mapCompanies" :key="c.id"><button v-if="mapCell(c.id,t).length" class="matrix-claim" @click="mapEvents=mapCell(c.id,t)"><strong>{{mapCell(c.id,t).length}} 条证据记录 ↗</strong><p>{{[...new Set(mapCell(c.id,t).map(e=>label(e.progress_stage)))].join(' / ')}}</p></button><span v-else class="muted">暂无该方向记录</span></td></tr></tbody></table></div></section><el-dialog :model-value="mapEvents.length>0" @close="mapEvents=[]" title="技术方向相关事件" width="min(900px,95vw)"><div class="claim" v-for="e in mapEvents" :key="e.id"><h3>{{e.title}}</h3><p>{{e.description}}</p><p>{{label(e.progress_stage)}} · {{label(e.evidence_level)}}</p><el-button link @click="showEvidence(e)">查看原始证据</el-button></div></el-dialog></template>
<template v-else><section v-for="e in events" :key="e.id" class="panel"><div class="section-heading"><router-link :to="'/companies/'+e.company_id">{{names(e.company_id)}}</router-link><span class="pill">{{label(e.event_type)}} · {{label(e.progress_stage)}}</span></div><h2>{{e.title}}</h2><p>{{e.description}}</p><p>文章发布时间：{{e.published_at||'unknown'}} · 事件时间：{{e.occurred_at||'unknown'}}</p><p>技术方向：{{e.capability_tags.join(' / ')||'unknown'}}</p><p v-for="(metric,i) in e.metrics" :key="i">{{metric.name}}：{{metric.value}} {{metric.unit}}</p><span class="pill">{{label(e.evidence_level)}} · 原文匹配验证（不等于独立证实）</span> <el-button link @click="showEvidence(e)">原始证据 ↗</el-button></section></template><el-empty v-if="!events.length" description="尚无匹配事件。导入真实文章并执行提取；不会生成虚构动态。"/></template>
<el-dialog v-model="dialog" title="新增企业" width="min(560px,90vw)"><el-form label-position="top"><el-form-item label="企业名称"><el-input v-model="form.name"/></el-form-item><el-form-item label="分类"><el-input v-model="form.category"/></el-form-item><el-form-item label="官网"><el-input v-model="form.official_url"/></el-form-item><el-form-item label="简介"><el-input v-model="form.description" type="textarea"/></el-form-item><el-button type="primary" @click="save">保存</el-button></el-form></el-dialog>
<el-dialog v-model="sourceDialog" title="添加公开数据源" width="min(600px,90vw)"><el-form label-position="top"><el-form-item label="企业"><el-select v-model="source.company_id"><el-option v-for="c in companies" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="URL（公众号为单篇文章，arXiv 为 abs 链接）"><el-input v-model="source.url"/></el-form-item><el-form-item label="来源类型"><el-select v-model="source.source_type"><el-option v-for="t in types" :key="t" :label="t" :value="t"/></el-select></el-form-item><el-form-item label="来源证据等级（独立测试/客户作者身份须人工核实后选择）"><el-select v-model="source.evidence_authority"><el-option v-for="l in ['company_claim','technical_artifact','independent_verification','customer_confirmation']" :key="l" :label="label(l)" :value="l"/></el-select></el-form-item><el-button type="primary" @click="addSource">保存来源</el-button></el-form></el-dialog>
<el-dialog v-model="projectDialog" title="添加企业项目"><el-input v-model="project.name" placeholder="项目名"/><el-button @click="saveProject">保存项目</el-button></el-dialog>
<el-drawer v-model="drawer" title="公开证据与历史快照" size="min(760px,95vw)"><template v-if="evidence"><p>{{label(evidence.evidence_level)}} · <a :href="evidence.source_url" target="_blank" rel="noopener noreferrer">原文 ↗</a></p><blockquote>{{evidence.evidence_text}}</blockquote><p>Snapshot #{{evidence.snapshot_id}}</p><pre class="snapshot-text">{{snapshot?.content}}</pre></template><template v-for="s in snapshots" :key="s.id"><h3>Snapshot #{{s.id}} · {{s.created_at}}</h3><el-button type="primary" @click="runSnapshot(s.id)">提取企业进展</el-button><pre class="snapshot-text">{{s.content}}</pre></template><el-empty v-if="!evidence&&!snapshots.length" description="暂无快照，请先采集"/></el-drawer>
<el-dialog :model-value="!!report" @close="report=null" title="行业周报" width="min(900px,95vw)"><el-button @click="download">下载 Markdown</el-button><pre>{{report?.markdown}}</pre></el-dialog>
</div></template>
